// Manual numerical validation tool. Inputs are generated by the independent
// Python QA script; this is not an App/CLI spectral profile interchange format.
#include "photonstack/FitsCodec.hpp"
#include "photonstack/SpectralCalibration.hpp"
#include "photonstack/SpectralCalibrator.hpp"
#include "photonstack/StellarPhotometry.hpp"
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
using namespace photonstack;
namespace {
SpectralCurve curve(std::istream& in) {
    unsigned n = 0;
    in >> n;
    if (n < 2 || n > 100000)
        throw std::invalid_argument("Invalid probe curve length");
    SpectralCurve c;
    c.wavelength.resize(n);
    c.value.resize(n);
    for (unsigned i = 0; i < n; ++i)
        in >> c.wavelength[i] >> c.value[i];
    return c;
}
template <class T> void array(const T& a) {
    std::cout << '[';
    bool first = true;
    for (auto x : a) {
        if (!first)
            std::cout << ',';
        first = false;
        std::cout << x;
    }
    std::cout << ']';
}
} // namespace
int main(int argc, char** argv) {
    try {
        if (argc != 3 && argc != 4)
            throw std::invalid_argument("Usage: probe linear-wcs.fits numeric-fixture.txt [new-calibrated.fits]");
        if (argc == 4 && std::filesystem::exists(argv[3]))
            throw std::invalid_argument("Probe output already exists");
        const auto source = readLinearScienceImage(argv[1]);
        if (!source.sky)
            throw std::invalid_argument("Probe needs WCS");
        std::ifstream in(argv[2]);
        std::array<SpectralBand, 3> bands;
        for (auto& band : bands) {
            unsigned n = 0;
            in >> n;
            if (n < 1 || n > 8)
                throw std::invalid_argument("Invalid probe band count");
            for (unsigned j = 0; j < n; ++j)
                band.push_back(curve(in));
        }
        SampledSpectrum white{curve(in), {}};
        std::array<double, 3> whiteFlux{};
        for (unsigned c = 0; c < 3; ++c)
            whiteFlux[c] = integratePhotonSpectrum(white, bands[c]).value;
        unsigned n = 0;
        in >> n;
        if (n > 10000)
            throw std::invalid_argument("Too many probe stars");
        std::vector<SpectralColorSample> samples;
        std::vector<SpectralReferenceStar> references;
        std::cout << std::setprecision(17) << "{\"white\":";
        array(whiteFlux);
        std::cout << ",\"stars\":[";
        for (unsigned i = 0; i < n; ++i) {
            std::string id;
            double ra = 0, dec = 0;
            in >> id >> ra >> dec;
            if (id.empty() || id.find_first_not_of("0123456789") != std::string::npos)
                throw std::invalid_argument("Probe uses numeric IDs");
            auto flux = curve(in), errors = curve(in);
            if (flux.wavelength != errors.wavelength)
                throw std::invalid_argument("Probe uncertainty sampling differs");
            SampledSpectrum spectrum{flux, errors.value};
            references.push_back({id, ra, dec, spectrum});
            std::array<double, 3> predicted{}, errorBound{}, mean{}, bandwidth{};
            for (unsigned c = 0; c < 3; ++c) {
                const auto f = integratePhotonSpectrum(spectrum, bands[c]);
                predicted[c] = f.value;
                errorBound[c] = f.errorBound;
                mean[c] = f.meanWavelength;
                bandwidth[c] = f.rmsBandwidth;
            }
            const auto p = SkyProjection(*source.sky, {1, 1, ra, dec, {1, 0, 0, 1}}).toPanel(0, 0);
            const auto measurement = measureStellarAperture(source.image, p.x, p.y);
            if (measurement.valid)
                samples.push_back({id, measurement.x, measurement.y, measurement.flux, predicted});
            if (i)
                std::cout << ',';
            std::cout << "{\"id\":\"" << id << "\",\"status\":\"" << measurement.status << "\",\"predictedX\":" << p.x
                      << ",\"predictedY\":" << p.y << ",\"x\":" << measurement.x << ",\"y\":" << measurement.y
                      << ",\"area\":" << measurement.area << ",\"predicted\":";
            array(predicted);
            std::cout << ",\"errorBound\":";
            array(errorBound);
            std::cout << ",\"meanWavelength\":";
            array(mean);
            std::cout << ",\"rmsBandwidth\":";
            array(bandwidth);
            std::cout << ",\"observed\":";
            array(measurement.flux);
            std::cout << ",\"skySigma\":";
            array(measurement.skySigma);
            std::cout << ",\"backgroundNoise\":";
            array(measurement.backgroundNoise);
            std::cout << ",\"snr\":";
            array(measurement.snr);
            std::cout << ",\"skyUsed\":";
            array(measurement.skyUsed);
            std::cout << ",\"skyPlane\":[";
            for (unsigned c = 0; c < 3; ++c) {
                if (c)
                    std::cout << ',';
                array(measurement.skyPlane[c]);
            }
            std::cout << "]}";
        }
        std::string extra;
        if (!in || in >> extra || !in.eof())
            throw std::invalid_argument("Invalid probe fixture");
        const auto fit = fitSpectralColors(samples, whiteFlux, source.image.width, source.image.height);
        std::cout << "],\"fit\":{\"valid\":" << (fit.valid ? "true" : "false")
                  << ",\"reason\":" << std::quoted(fit.reason) << ",\"training\":" << fit.training
                  << ",\"validation\":" << fit.validation << ",\"rejected\":" << fit.rejected
                  << ",\"regions\":" << fit.validationRegions << ",\"gains\":";
        array(fit.gains);
        std::cout << ",\"instrumentGains\":";
        array(fit.instrumentGains);
        std::cout << ",\"trainingScatter\":";
        array(fit.trainingScatter);
        std::cout << ",\"validationMedian\":";
        array(fit.validationMedian);
        std::cout << ",\"validationP90\":";
        array(fit.validationP90);
        std::cout << ",\"stars\":[";
        for (std::size_t i = 0; i < fit.stars.size(); ++i) {
            const auto& s = fit.stars[i];
            if (i)
                std::cout << ',';
            std::cout << "{\"id\":" << std::quoted(s.id) << ",\"status\":" << std::quoted(s.status) << ",\"residual\":";
            array(s.residual);
            std::cout << '}';
        }
        std::cout << "]},\"review\":{";
        const auto review = reviewSpectralCalibration(source.image, *source.sky, references, bands, white);
        std::cout << "\"valid\":" << (review.fit.valid ? "true" : "false")
                  << ",\"reason\":" << std::quoted(review.fit.reason) << ",\"detected\":" << review.detected
                  << ",\"training\":" << review.fit.training << ",\"validation\":" << review.fit.validation
                  << ",\"rejected\":" << review.fit.rejected << ",\"regions\":" << review.fit.validationRegions
                  << ",\"gains\":";
        array(review.fit.gains);
        std::cout << ",\"instrumentGains\":";
        array(review.fit.instrumentGains);
        std::cout << ",\"trainingScatter\":";
        array(review.fit.trainingScatter);
        std::cout << ",\"validationMedian\":";
        array(review.fit.validationMedian);
        std::cout << ",\"validationP90\":";
        array(review.fit.validationP90);
        std::cout << ",\"stars\":[";
        for (std::size_t i = 0; i < review.stars.size(); ++i) {
            const auto& s = review.stars[i];
            if (i)
                std::cout << ',';
            std::cout << "{\"id\":" << std::quoted(s.id) << ",\"status\":" << std::quoted(s.status)
                      << ",\"x\":" << s.photometry.x << ",\"y\":" << s.photometry.y
                      << ",\"expandedX\":" << s.expandedPhotometry.x << ",\"expandedY\":" << s.expandedPhotometry.y
                      << ",\"apertureColorChange\":";
            array(s.apertureColorChange);
            std::cout << ",\"observed\":";
            array(s.photometry.flux);
            std::cout << ",\"expandedFlux\":";
            array(s.expandedPhotometry.flux);
            std::cout << '}';
        }
        std::cout << "],\"fitStars\":[";
        for (std::size_t i = 0; i < review.fit.stars.size(); ++i) {
            const auto& s = review.fit.stars[i];
            if (i)
                std::cout << ',';
            std::cout << "{\"id\":" << std::quoted(s.id) << ",\"status\":" << std::quoted(s.status) << ",\"residual\":";
            array(s.residual);
            std::cout << '}';
        }
        std::cout << "]}}\n";
        if (argc == 4 && review.fit.valid) {
            const auto calibrated = applySpectralCalibration(source.image, review.fit);
            const auto written = FitsCodec().write(calibrated, argv[3], &source.sky->grid, &source.sky->distortion);
            if (!written.ok)
                throw std::runtime_error(written.message);
        }
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
